package kvpress.routea.rtl3

import chisel3._
import chisel3.util.{Cat, Enum, RegEnable, Valid}
import kvpress.routea.interfaces._
import kvpress.routea.params.{RouteAAnchorWidths, RouteASkeletonParameters}

import scala.io.Source

/**
  * Immutable test-resource values generated by the Python functional partial
  * provider and functional R4 oracle.  This parser belongs in test scope: it
  * is never a hardware loader or a production implementation choice.
  */
final case class RouteARTL36bFixture(
    requestId: Int,
    incarnation: Int,
    sourceKind: Int,
    sourceCoordinate: Int,
    sourceGeneration: Int,
    sourcePresence: Int,
    headers: Vector[BigInt],
    fragments: Vector[BigInt],
    result: BigInt,
)

object RouteARTL36bFixture {
  private val Resource = "rtl3_6b_functional_provider_terminal.fixture"
  private val Schema = "kvzap-route-a-rtl3-6b-functional-provider-terminal-fixture-1.0"

  lazy val load: RouteARTL36bFixture = {
    val source = Source.fromResource(Resource)
    val fields = try {
      source.getLines().map(_.trim).filter(line => line.nonEmpty && !line.startsWith("#")).map { line =>
        val pair = line.split("=", 2)
        require(pair.length == 2, s"malformed RTL3.6-B fixture line: $line")
        pair(0) -> pair(1)
      }.toMap
    } finally source.close()
    def decimal(key: String): Int = fields.getOrElse(key, throw new IllegalArgumentException(s"missing $key")).toInt
    def word(key: String): BigInt = BigInt(fields.getOrElse(key, throw new IllegalArgumentException(s"missing $key")), 16)
    require(fields.get("schema_version").contains(Schema), "RTL3.6-B fixture schema drift")
    RouteARTL36bFixture(
      requestId = decimal("request_id"),
      incarnation = decimal("incarnation"),
      sourceKind = decimal("source_kind"),
      sourceCoordinate = decimal("source_instance_coordinate"),
      sourceGeneration = decimal("source_generation"),
      sourcePresence = decimal("source_presence"),
      headers = Vector.tabulate(4)(consumer => word(s"header_consumer_${consumer}_word_hex")),
      fragments = Vector.tabulate(8)(fragment => word(s"fragment_${fragment}_word_hex")),
      result = word("result_word_hex"),
    )
  }
}

/**
  * Replay only the static Python functional-provider packet bytes after the
  * existing packed owner announces availability.  The module is test-only: it
  * does not compute attention, own an S2 slot, or select a source plan.
  */
final class RouteARTL36bPackedFixtureProvider(p: RouteASkeletonParameters, fixture: RouteARTL36bFixture) extends Module {
  override def desiredName: String = "testbench_route_a_rtl3_6b_packed_fixture_provider"
  val io = IO(new Bundle {
    val availability_in = Input(new SourceServiceAvailability(p))
    val packed_offer_out = RouteAChannels.source_service_partial_offer(p)
    val packed_fragment_out = RouteAChannels.source_service_value_fragment(p)
    val complete = Output(Bool())
  })

  val idle :: offer :: fragments :: done :: Nil = Enum(4)
  val state = RegInit(idle)
  val heldIdentity = Reg(new TransactionIdentity)
  val heldInstance = Reg(new SourceInstance(p))
  val consumer = RegInit(0.U(RouteAAnchorWidths.ConsumerIdWidth.W))
  val fragment = RegInit(0.U(3.W))
  val headerWords = VecInit(fixture.headers.map(_.U(RouteAAnchorWidths.MergePartialHeaderWidth.W)))
  val fragmentWords = VecInit(fixture.fragments.map(_.U(RouteAAnchorWidths.MergeValueFragmentWidth.W)))

  when(state === idle && io.availability_in.valid) {
    heldIdentity := io.availability_in.transaction_identity
    heldInstance := io.availability_in.source_instance
    state := offer
  }
  io.packed_offer_out.valid := state === offer
  io.packed_offer_out.bits.transaction_identity := heldIdentity
  io.packed_offer_out.bits.source_instance := heldInstance
  io.packed_offer_out.bits.consumer_id := consumer
  io.packed_offer_out.bits.r4_header := headerWords(consumer)
  io.packed_offer_out.bits.partial_present := true.B
  when(io.packed_offer_out.fire) {
    fragment := 0.U
    state := fragments
  }

  io.packed_fragment_out.valid := state === fragments
  io.packed_fragment_out.bits.transaction_identity := heldIdentity
  io.packed_fragment_out.bits.source_instance := heldInstance
  io.packed_fragment_out.bits.consumer_id := consumer
  io.packed_fragment_out.bits.fragment_index := fragment
  io.packed_fragment_out.bits.last := fragment === 7.U
  io.packed_fragment_out.bits.data := fragmentWords(fragment)
  when(io.packed_fragment_out.fire) {
    when(fragment === 7.U) {
      when(consumer === 3.U) { state := done }.otherwise { consumer := consumer + 1.U; state := offer }
    }.otherwise { fragment := fragment + 1.U }
  }
  io.complete := state === done

  val heldOffer = RegEnable(io.packed_offer_out.bits,
    io.packed_offer_out.valid && !io.packed_offer_out.ready)
  when(RegNext(io.packed_offer_out.valid && !io.packed_offer_out.ready, false.B)) {
    assert(io.packed_offer_out.valid && io.packed_offer_out.bits.asUInt === heldOffer.asUInt)
  }
  val heldFragment = RegEnable(io.packed_fragment_out.bits,
    io.packed_fragment_out.valid && !io.packed_fragment_out.ready)
  when(RegNext(io.packed_fragment_out.valid && !io.packed_fragment_out.ready, false.B)) {
    assert(io.packed_fragment_out.valid && io.packed_fragment_out.bits.asUInt === heldFragment.asUInt)
  }
}

/**
  * Test-only bridge from structural R4 acceptance to static functional-oracle
  * terminal bytes.  A success carrier is offered only after all four exact
  * fixture packets have crossed the real structural acceptance boundary.
  */
final class RouteARTL36bFunctionalTerminalFixture(p: RouteASkeletonParameters, fixture: RouteARTL36bFixture) extends Module {
  override def desiredName: String = "testbench_route_a_rtl3_6b_functional_terminal_fixture"
  val io = IO(new Bundle {
    val accepted_packet_in = Flipped(RouteAChannels.r4_accepted_partial_packet(p))
    val active_merge_observation = Input(Valid(new MergeRequest))
    val r4_result_stub_out = RouteAChannels.r4_result_stub
    val r4_numeric_fault_out = RouteAChannels.r4_numeric_fault
    val all_packets_accepted = Output(Bool())
  })

  private def identityMatches(identity: TransactionIdentity): Bool =
    identity.request_id === fixture.requestId.U && identity.incarnation === fixture.incarnation.U

  val headerWords = VecInit(fixture.headers.map(_.U(RouteAAnchorWidths.MergePartialHeaderWidth.W)))
  val payloadWord = Cat(fixture.fragments.reverse.map(_.U(RouteAAnchorWidths.MergeValueFragmentWidth.W)))
  val packetMask = RegInit(0.U(4.W))
  val completedMask = RegInit(0.U(4.W))
  val held = RegInit(false.B)
  val heldConsumer = Reg(UInt(RouteAAnchorWidths.ConsumerIdWidth.W))
  val completedIdentity = Reg(new TransactionIdentity)
  val completionQuiesced = RegInit(false.B)

  val accepted = io.accepted_packet_in.bits
  val packetConsumerLegal = accepted.consumer_id < 4.U
  val packetMatches = packetConsumerLegal && identityMatches(accepted.transaction_identity) &&
    accepted.source_instance.source_kind === fixture.sourceKind.U &&
    accepted.source_instance.instance_coordinate === fixture.sourceCoordinate.U &&
    accepted.source_instance.generation === fixture.sourceGeneration.U &&
    accepted.header === headerWords(accepted.consumer_id) && accepted.value_payload === payloadWord
  io.accepted_packet_in.ready := packetMatches && !packetMask(accepted.consumer_id)
  when(io.accepted_packet_in.fire) { packetMask := packetMask | (1.U << accepted.consumer_id) }
  io.all_packets_accepted := packetMask === "b1111".U

  val active = io.active_merge_observation
  val activeMatches = active.valid && identityMatches(active.bits.transaction_identity) &&
    active.bits.source_presence === fixture.sourcePresence.U && active.bits.consumer_id < 4.U
  val activeAlreadyCompleted = completedMask(active.bits.consumer_id)
  when(completionQuiesced && (!active.valid || active.bits.transaction_identity.asUInt =/= completedIdentity.asUInt)) {
    completionQuiesced := false.B
  }
  when(!held && !completionQuiesced && packetMask === "b1111".U && activeMatches && !activeAlreadyCompleted) {
    held := true.B
    heldConsumer := active.bits.consumer_id
  }

  io.r4_result_stub_out.valid := held
  io.r4_result_stub_out.bits.transaction_identity.request_id := fixture.requestId.U
  io.r4_result_stub_out.bits.transaction_identity.incarnation := fixture.incarnation.U
  io.r4_result_stub_out.bits.consumer_id := heldConsumer
  io.r4_result_stub_out.bits.normalized_value := fixture.result.U(RouteAAnchorWidths.NormalizedValueWidth.W)
  io.r4_numeric_fault_out.valid := false.B
  io.r4_numeric_fault_out.bits.transaction_identity := 0.U.asTypeOf(new TransactionIdentity)
  io.r4_numeric_fault_out.bits.consumer_id := 0.U
  when(io.r4_result_stub_out.fire) {
    held := false.B
    completedMask := completedMask | (1.U << heldConsumer)
    completionQuiesced := true.B
    completedIdentity := io.r4_result_stub_out.bits.transaction_identity
  }

  assert(!(io.r4_result_stub_out.valid && io.r4_numeric_fault_out.valid))
  when(io.accepted_packet_in.fire) { assert(packetMatches) }
  when(io.r4_result_stub_out.fire) {
    assert(packetMask === "b1111".U && activeMatches && !activeAlreadyCompleted)
  }
  val heldResult = RegEnable(io.r4_result_stub_out.bits,
    io.r4_result_stub_out.valid && !io.r4_result_stub_out.ready)
  when(RegNext(io.r4_result_stub_out.valid && !io.r4_result_stub_out.ready, false.B)) {
    assert(io.r4_result_stub_out.valid && io.r4_result_stub_out.bits.asUInt === heldResult.asUInt)
  }
}
